<script lang="ts">
 import {timeAudience,clockLabel,type TimePerson,type Window} from './time-audience';
 import {platformClass} from './period';
 import Help from './Help.svelte';
 let {windows,people,timezone='Europe/Moscow',onPerson}:{windows:Window[];people:TimePerson[];timezone?:string;onPerson:(id:string)=>void}=$props();
 let day=$state('all'),hour=$state<number|null>(null),resolution=$state(60),selected=$state<number|null>(null);
 const buckets=$derived(timeAudience(windows,people,timezone,resolution,day,hour));
 const chosen=$derived(buckets.find(b=>b.minute===selected));
 const maximum=$derived(Math.max(1,...buckets.map(b=>b.people.size)));
 const byId=$derived(new Map(people.map(p=>[p.id,p])));
 const visitors=$derived(chosen?[...chosen.people].map(([id,sessions])=>({person:byId.get(id)!,visits:sessions.size,total:chosen.streams.size})).sort((a,b)=>b.visits-a.visits||a.person.name.localeCompare(b.person.name)):[]);
 $effect(()=>{void day;void hour;void resolution;selected=null;});
</script>
<section class="panel time-audience"><header><h2>Кто бывает в это время</h2><Help id="time-attendance-help" label="О явке по времени" text="Явка = число стримов с сигналом этого человека в выбранном интервале / число стримов, шедших в этом интервале. Один стрим учитывается один раз, даже если было несколько сообщений или перерывов. Учитываются наблюдения Twitch и сообщения; YouTube после сообщения — оценка активности, не подтверждение просмотра. Нажмите час, затем выберите детализацию до минуты."/></header>
 <div class="controls"><label>День активности<select bind:value={day}><option value="all">Все дни</option>{#each ['пн','вт','ср','чт','пт','сб','вс'] as d}<option value={d}>{d}</option>{/each}</select></label><label>Час для детализации<select bind:value={hour} onchange={()=>resolution=hour===null?60:15}><option value={null}>Весь день</option>{#each Array.from({length:24},(_,i)=>i) as h}<option value={h}>{clockLabel(h*60)}</option>{/each}</select></label>{#if hour!==null}<label>Шаг активности<select bind:value={resolution}><option value={15}>15 минут</option><option value={5}>5 минут</option><option value={1}>1 минута</option></select></label>{/if}</div>
 <div class="slots" style:grid-template-columns={`repeat(${buckets.length},minmax(0,1fr))`} aria-label="Таймлайн аудитории по времени суток">{#each buckets as b}<button class:chosen={selected===b.minute} disabled={!b.streams.size} aria-label={`${clockLabel(b.minute)} · ${b.people.size} людей · ${b.streams.size} стримов`} onclick={()=>selected=b.minute} title={`${clockLabel(b.minute)}: ${b.people.size} людей, ${b.streams.size} стримов`}><i style:height={`${b.people.size/maximum*100}%`}></i>{#if buckets.length<=24}<span>{hour===null?Math.floor(b.minute/60):b.minute%60}</span>{/if}</button>{/each}</div>
 {#if chosen}<div class="slot-heading"><strong>{clockLabel(chosen.minute)}–{clockLabel(chosen.minute+resolution)} · {chosen.streams.size} стримов</strong>{#if hour===null}<button class="outline small" onclick={()=>{hour=Math.floor(chosen.minute/60);resolution=15;}}>Подробно по минутам</button>{/if}</div>
 <div class="table-wrap compact-data"><table><thead><tr><th>Человек</th><th>Явка в это время</th><th>Посещено / шло эфиров</th></tr></thead><tbody>{#each visitors as v}<tr><td><button class={`text-button ${platformClass(v.person.sources??[v.person.source??''])}`} onclick={()=>onPerson(v.person.id)}>{v.person.name}</button></td><td>{Math.round(v.visits/v.total*100)}%</td><td>{v.visits} / {v.total}</td></tr>{/each}</tbody></table></div>{#if !visitors.length}<p class="empty-small">Персональных сигналов в этом интервале нет.</p>{/if}{:else}<p class="small muted hint">Нажмите столбец: увидите людей и их явку среди эфиров в это время.</p>{/if}
</section>
<style>.controls{display:flex;flex-wrap:wrap;gap:12px;padding:16px 20px}label{display:grid;gap:6px;font-size:12px;flex:1 1 150px}select{width:100%;min-width:0}.slots{display:grid;gap:3px;align-items:end;height:130px;margin:12px 20px 32px}.slots button{position:relative;height:100%;padding:0;background:#222833;border:0;border-radius:3px}.slots button:disabled{opacity:.35}.slots button i{position:absolute;bottom:0;left:0;right:0;background:var(--teal);border-radius:3px}.slots button.chosen{outline:2px solid var(--accent)}.slots button span{position:absolute;top:100%;left:0;right:0;font-size:10px;color:var(--muted);margin-top:6px}.slot-heading{display:flex;flex-wrap:wrap;gap:12px;justify-content:space-between;padding:12px 20px}.hint{padding:0 20px 16px}.compact-data{max-height:420px;overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:12px;text-align:left;border-bottom:1px solid var(--border);font-size:12px}td button{white-space:normal;overflow-wrap:anywhere}.twitch{color:var(--twitch,#a970ff)}.youtube{color:var(--youtube,#ff5959)}</style>
